  --kerykeion-chart-color-zodiac-bg-4: var(--kerykeion-color-base-200);
  --kerykeion-chart-color-zodiac-bg-5: var(--kerykeion-color-base-300);
  --kerykeion-chart-color-zodiac-bg-6: var(--kerykeion-color-base-200);
